import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { ArrowDownLeft, ArrowDownUp, ArrowLeft, ArrowRight, ArrowUpRight, Banknote, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Circle, CircleAlert, Coffee, CreditCard, Gift, GraduationCap, Heart, HeartPulse, House, Landmark, LoaderCircle, Music, Pencil, PiggyBank, Plus, RefreshCw, Settings2, ShieldCheck, ShoppingBag, Smartphone, Tag, TrainFront, Trash2, Utensils, Wallet, X, type LucideIcon } from 'lucide-react';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
