  const [report, setReport] = useState<FinanceReport | null>(null); const [monthReport, setMonthReport] = useState<FinanceReport | null>(null);
  const [entries, setEntries] = useState<FinanceEntries | null>(null);
  const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const [revision, setRevision] = useState(0); const [busy, setBusy] = useState(false); const busyRef = useRef(false);
  const [uncertain, setUncertain] = useState(false); const submission = useRef(createFinanceSubmissionGuard<PendingOperation>());
